def subtract(a, b):
    # Filter out empty intervals and sort
    a_filtered = sorted([interval for interval in a if interval[0] < interval[1]])
    b_filtered = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_filtered:
        return []

    # Merge overlapping/touching intervals in b
    b_merged = []
    for start, end in b_filtered:
        if b_merged and start <= b_merged[-1][1]:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Merge overlapping/touching intervals in a
    a_merged = []
    for start, end in a_filtered:
        if a_merged and start <= a_merged[-1][1]:
            a_merged[-1][1] = max(a_merged[-1][1], end)
        else:
            a_merged.append([start, end])

    result = []

    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                if b_end <= curr_start or b_start >= curr_end:
                    # No overlap
                    new_ranges.append([curr_start, curr_end])
                else:
                    # There is overlap, keep the parts outside b
                    if curr_start < b_start:
                        new_ranges.append([curr_start, b_start])
                    if b_end < curr_end:
                        new_ranges.append([b_end, curr_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    return result

